"use strict";

import TreeEqualizer from "../treeEqualizer.js";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("EditPortfolioCtrl", ($scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams, downloadService) => {

		angular.extend($scope,
		{
			data: {
				language: language,
				portfolioId: $routeParams.portfolioId,
				groupId: parseInt($routeParams.groupId)
			},
			ready: true
		});

		$scope.refresh = () => {
			$http.get(`/webapi/portfolios/${$scope.data.portfolioId}`)
				.then((response) => {
					$scope.data.portfolio = response.data;

					const equalizer = new TreeEqualizer($scope.data.portfolio.groups, (g) => g.order);
					$scope.data.groups = equalizer.execute();

					//todo. более явный критерий
					$scope.project = typeof ($scope.data.portfolio.leaders) != "undefined";
					const currentGroupId = ($scope.data.group && $scope.data.group.id) || $scope.data.groupId;
					if (currentGroupId) {
						$scope.data.group = _.findWhere($scope.data.groups, { id: currentGroupId });
					}
					if (!$scope.data.group) {
						$scope.data.group = _.first($scope.data.groups);
					}
					$appLoader.hide();
				});
		}
		$scope.refresh();

		//добавить раздел
		$scope.addGroup = (parentGroup) => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/portfolio/common/edit/editGroupTemplate.html",
				controller: "EditPortfolioGroupCtrl",
				size: "md",
				resolve: {
					portfolio: () => $scope.data.portfolio,
					parentGroup: () => parentGroup,
					group: () => { return { editing: true }; }
				}
			});

			modalInstance.result.then(() => {
				$appLoader.show();
				$scope.refresh();
			});
		}

		//редактировать раздел
		$scope.editGroup = (group) => {
			const parentGroup = _.findWhere($scope.data.groups, { id: group.parentGroupId });

			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/portfolio/common/edit/editGroupTemplate.html",
				controller: "EditPortfolioGroupCtrl",
				size: "md",
				resolve: {
					portfolio: () => $scope.data.portfolio,
					parentGroup: () => parentGroup,
					group: () => angular.extend({ editing: true }, group)
				}
			});

			modalInstance.result.then(() => {
				$appLoader.show();
				$scope.refresh();
			});
		}
		
		$scope.openDoc = (url, fileName) => {
			downloadService.downloadFile(url, fileName);
		}

		//удалить раздел
		$scope.removeGroup = (group) => {
			const url = `/webapi/portfolios/${$scope.data.portfolioId}/groups/${group.id}`;
			$dialogs.confirm("Вы действительно желаете удалить раздел?")
				.then(() => $http.delete(url))
				.then(() => {
					$appLoader.show();
					$scope.refresh();
					$alerts.success("Раздел успешно удален");
				}).catch((response) => {
					$alerts.error(response.data.message, response.data.details);
				});
		}

		//добавить ссылку
		$scope.addLink = () => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/portfolio/common/edit/editlinktemplate.html",
				controller: "EditPortfolioLinkCtrl",
				size: "md",
				resolve: {
					portfolioId: () => $scope.data.portfolio.id,
					group: () => $scope.data.group,
					link: () => { return {}; }
				}
			});

			modalInstance.result.then((createdLink) => {
				$scope.data.group.links.push(createdLink);
			});
		}

		//редактировать ссылку
		$scope.editLink = (link) => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/portfolio/common/edit/editlinktemplate.html",
				controller: "EditPortfolioLinkCtrl",
				size: "md",
				resolve: {
					portfolioId: () => $scope.data.portfolio.id,
					group: () => $scope.data.group,
					link: () => angular.extend({}, link)
				}
			});

			modalInstance.result.then((editedLink) => {
				link = angular.extend(link, editedLink);
			});
		}

		//удалить ссылку
		$scope.removeLink = (link) => {
			const url = `/webapi/portfolios/${$scope.data.portfolioId}/groups/${$scope.data.group.id}/links/${link.id}`;
			$dialogs.confirm("Вы действительно желаете удалить ссылку?")
				.then(() => $http.delete(url))
				.then(() => {
					$scope.data.group.links = _.without($scope.data.group.links, link);
					$appLoader.show();
					$scope.refresh();
					$alerts.success("Ссылка успешно удалена");
				}).catch((response) => {
					$alerts.error(response.data.message, response.data.details);
				});
		}


		//добавить документ
		$scope.addDoc = () => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/portfolio/common/edit/editDocTemplate.html",
				controller: "EditPortfolioDocCtrl",
				size: "md",
				resolve: {
					portfolioId: () => $scope.data.portfolio.id,
					group: () => $scope.data.group,
					doc: () => { return {}; }
				}
			});

			modalInstance.result.then((createddoc) => {
				$scope.data.group.docs.push(createddoc);
			});
		}

		//редактировать документ
		$scope.editDoc = (doc) => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/portfolio/common/edit/editDocTemplate.html",
				controller: "EditPortfolioDocCtrl",
				size: "md",
				resolve: {
					portfolioId: () => $scope.data.portfolio.id,
					group: () => $scope.data.group,
					doc: () => angular.extend({}, doc)
				}
			});

			modalInstance.result.then((editeddoc) => {
				doc = angular.extend(doc, editeddoc);
			});
		}

		//удалить документ
		$scope.removeDoc = (doc) => {
			const url = `/webapi/portfolios/${$scope.data.portfolioId}/groups/${$scope.data.group.id}/docs/${doc.id}`;

			$dialogs.confirm("Вы действительно желаете удалить документ?")
				.then(() => $http.delete(url))
				.then(() => {
					$scope.data.group.docs = _.without($scope.data.group.docs, doc);
					$appLoader.show();
					$scope.refresh();
					$alerts.success("Документ успешно удален");
				}).catch((response) => {
					$alerts.error(response.data.message, response.data.details);
				});
		}

	})
	.controller("EditPortfolioGroupCtrl", ($scope, $http, $alerts, $uibModalInstance, $longWork, portfolio, parentGroup, group) => {
		$scope.editMode = group.id > 0;
		$scope.header = $scope.editMode ? "Редактирование раздела" : "Создание раздела";

		angular.extend($scope, {
			language: language,
			data: {
				portfolio: portfolio,
				parentGroup: parentGroup,
				group: group
			}
		});

		const treeIndexer = {};

		class GroupTreeItem {
			constructor(group, parent, subGroups) {
				this.parent = parent;
				this.id = group.id;
				if (this.id === $scope.data.group.id) {
					this.group = $scope.data.group;
				} else {
					this.group = group;
				}
				this.editing = false;
				this.groups = _.map(subGroups, (subItem) => new GroupTreeItem(subItem, group, subItem.groups));

				treeIndexer[this.id] = this;
			}
		}

		$scope.data.tree = _.chain(portfolio.groups)
			.map((group) => new GroupTreeItem(group, null, group.groups))
			.sortBy((group) => group.sortOrder)
			.value();

		if (!group.id) {
			//создание нового раздела
			const newItem = new GroupTreeItem($scope.data.group, parentGroup, []);
			newItem.editing = true;
			$scope.data.group.order = 1;
			let parentTreeItem;

			if (parentGroup == null) {
				parentTreeItem = {groups: $scope.data.tree}
			} else {
				parentTreeItem = treeIndexer[parentGroup.id];
				$scope.data.group.parentGroupId = parentGroup.id;
			}

			if (parentTreeItem.groups.length) {
				$scope.data.group.order = _.chain(parentTreeItem.groups).map((i) => i.group.order).max().value() + 1;
			}
			parentTreeItem.groups.push(newItem);
		} else {
			const treeItem = treeIndexer[group.id];
			treeItem.editing = true;
		}

		$scope.treeOptions = {
			beforeDrag: (event) => {
				return event.$modelValue.id === $scope.data.group.id;
			},
			dropped: (event) => {
				$scope.data.group.order = event.dest.index + 1;
				const parentNodeScope = event.dest.nodesScope.$nodeScope;
				if (parentNodeScope == null) {
					$scope.data.group.parentGroupId = null;
				} else {
					$scope.data.group.parentGroupId = parentNodeScope.$modelValue.id;
				}
			}
		};

		$scope.save = () => {
			if (!$scope.groupForm.$valid) {
				$scope.groupForm.$displayErrors = true;
				return;
			}

			let url = `/webapi/portfolios/${$scope.data.portfolio.id}/groups/`;

			if ($scope.editMode) {
				url += $scope.data.group.id;

				$http.put(url, $scope.data.group)
					.then((response) => {
						$uibModalInstance.close(response.data);
						$alerts.success("Раздел успешно изменен");
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			} else {
				$http.post(url, $scope.data.group)
					.then((response) => {
						$uibModalInstance.close(response.data);
						$alerts.success("Раздел успешно создан");
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			}
		};

		$scope.cancel = () => {
			$uibModalInstance.dismiss("cancel");
		}

	})
	.controller("EditPortfolioLinkCtrl", ($scope, $http, $alerts, $uibModalInstance, $longWork, portfolioId, group, link) => {
		$scope.editMode = link.id > 0;
		$scope.header = $scope.editMode ? "Редактирование ссылки" : "Создание ссылки";

		angular.extend($scope, {
			language: language,
			data: {
				portfolioId: portfolioId,
				group: group,
				link: link
			}
		});

		$scope.save = () => {
			if (!$scope.linkForm.$valid) {
				$scope.linkForm.$displayErrors = true;
				return;
			}

			let url = `/webapi/portfolios/${$scope.data.portfolioId}/groups/${$scope.data.group.id}/links/`;

			if ($scope.editMode) {
				url += $scope.data.link.id;

				$http.put(url, $scope.data.link)
					.then((response) => {
						$uibModalInstance.close(response.data);
						$alerts.success("Ссылка успешно изменена");
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			} else {
				$http.post(url, $scope.data.link)
					.then((response) => {
						$uibModalInstance.close(response.data);
						$alerts.success("Ссылка успешно создана");
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			}
		};

		$scope.cancel = () => {
			$uibModalInstance.dismiss("cancel");
		}

	})
	.controller("EditPortfolioDocCtrl", ($scope, $http, $alerts, $uibModalInstance, $longWork, Upload, portfolioId, group, doc) => {
		$scope.editMode = doc.id > 0;
		$scope.header = $scope.editMode ? "Редактирование документа" : "Создание документа";

		angular.extend($scope, {
			language: language,
			data: {
				portfolioId: portfolioId,
				group: group,
				doc: doc
			}
		});

		$scope.$watch("data.doc.file", (file) => {
			if (file) {
				$scope.data.doc.fileName = file.name;
			}
		});
		
		$scope.save = () => {
			if (!$scope.docForm.$valid) {
				$scope.docForm.$displayErrors = true;
				return;
			}

			let url = `/webapi/portfolios/${$scope.data.portfolioId}/groups/${$scope.data.group.id}/docs/`;
			let method = "POST";

			if ($scope.editMode) {
				url += $scope.data.doc.id;
				method = "PUT";
			} 

			Upload.upload({
				url: url,
				method: method,
				data: {
					file: $scope.data.doc.file,
					info: JSON.stringify({
						Id: doc.id,
						Name: $scope.data.doc.name,
						Description: $scope.data.doc.description
					})
				}
			})
			.then(
				(response) => {
					$uibModalInstance.close(response.data);
					$alerts.success("Документ успешно сохранен");
				},
				(response) => {
					$alerts.error(response.data.message, response.data.details);
				}
			);
		};

		$scope.cancel = () => {
			$uibModalInstance.dismiss("cancel");
		}
	});


