"use strict";

import SearchSource from "approot/global/searchSource.js";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("EditPortfolioLeadersCtrl",
		($scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams) => {

			$scope.$parent.page = {
				parent: {
					title: language.Generic.SetupSchoolPortfolio.kTitleProjectPortfolios,
					href: `projects`
				},
				back: { history: true },
				title: language.Generic.SetupSchoolPortfolio.kPortfolioLeadersEditing
			}

			angular.extend($scope,
			{
				language: language,
				filter: {
					items: {
						userTypes: []
					},
					selected: {
						schoolId: parseInt($routeParams.schoolId) || null,
						userType: parseInt($routeParams.userType) || 1
					},
					ready: () => { return $scope.filter.selected.schoolId > 0; }
				},
				data: {
					portfolioId: $routeParams.portfolioId,
					leaders: [],
					selected: [],
					inheritance: false
				},
				paging: {
					page: 1,
					pageSize: 20,
					totalcount: 0
				},
				state: {
					ready: false,
					dataLoaded: false,
					dataChanged: false
				}
			});

			$appLoader.hide();

			$scope.searchCtx = new SearchSource({
				schools: {
					url: "/webapi/schools/search",
					searchParam: "name",
					params: { take: 20 }
				}
			}, $http);

			
			if ($scope.filter.selected.schoolId > 0) {
				$http.get(`/webapi/schools/short`, { params: { id: $scope.filter.selected.schoolId, withCityName: true } }).then(
					(response) => {
						$scope.searchCtx.schools.items = response.data;
					});
			}

			$http.get(`/webapi/portfolios/refs/userTypes`, { params: {onlyStuff: true} }).then((response) => {
				$scope.filter.items.userTypes = response.data;
			});

			$http.get(`/webapi/portfolios/${$scope.data.portfolioId}/leaders`)
				.then((response) => {
					$scope.data.selected = _.map(response.data, o => {return {id: o.userId, name: o.nickName}});
					$scope.state.ready = true;
				});

			$scope.disabled = (user) => {
				return user.id == appContext.userId;
			}

			$scope.selected = (leader) => {
				const id = leader.userId || leader.id;
				return _.findWhere($scope.data.selected, { id: id }) != null;
			}

			$scope.toggle = (leader) => {
				if ($scope.disabled(leader)) return;

				const searchResult = _.findWhere($scope.data.selected, { id: leader.id });
				if (searchResult) {
					$scope.data.selected = _.without($scope.data.selected, searchResult);
				} else {
					$scope.data.selected.push(leader);
				}

				$scope.state.dataChanged = true;
			}

			$scope.load = () => {
				const params = {
					schoolId: $scope.filter.selected.schoolId,
					page: $scope.paging.page,
					pageSize: $scope.paging.pageSize,
					userType: $scope.filter.selected.userType
				};

				$http.get(`/webapi/portfolios/leaders`, { params })
					.then((response) => {
						$scope.state.dataLoaded = true;
						$scope.data.users = response.data;
						$scope.paging.totalcount = parseInt(response.headers("count"));
						$scope.paging.show = $scope.paging.totalcount > $scope.paging.pageSize;
					});
			}

			$scope.save = () => {
				const setLeaders = _.map($scope.data.selected, o => {
					if (!o.id) 
						return o;
					return {
						userId: o.id,
						nickName: o.name
					}
				}
				);
				$http.put(`/webapi/portfolios/${$scope.data.portfolioId}/leaders`, setLeaders, { })
					.then(() => {
						$scope.state.dataChanged = false;
						$alerts.success("Руководители успешно сохранены");
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			}
		});


