"use strict";

import TreeEqualizer from "approot/school/portfolio/common/treeEqualizer.js";
import SearchSource from "approot/global/searchSource.js";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("EditPortfolioMembersCtrl",
		($scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams) => {

			$scope.$parent.page = {
				parent: {
					title: language.Generic.SetupSchoolPortfolio.kTitleProjectPortfolios,
					href: `projects`
				},
				back: { history: true },
				title: language.Generic.SetupSchoolPortfolio.kPortfolioMembersEditing
			}

			angular.extend($scope,
			{
				language: language,
				filter: {
					items: {
						groups: [],
						userTypes: []
					},
					selected: {
						schoolId: parseInt($routeParams.schoolId) || null,
						groupId: parseInt($routeParams.groupId) || -1,
						userType: parseInt($routeParams.userType) || -1
					},
					ready: () => { return $scope.filter.selected.schoolId > 0; }
				},
				data: {
					portfolioId: $routeParams.portfolioId,
					members: [],
					selected: [],
					inheritance: false
				},
				paging: {
					page: 1,
					pageSize: 20,
					totalcount: 0
				},
				state: {
					ready: false,
					dataLoaded: false,
					dataChanged: false
				}
			});

			$appLoader.hide();

			$scope.searchCtx = new SearchSource({
				schools: {
					url: "/webapi/schools/search",
					searchParam: "name",
					params: { take: 20 }
				}
			}, $http);

			
			if ($scope.filter.selected.schoolId > 0) {
				$http.get(`/webapi/schools/short`, { params: { id: $scope.filter.selected.schoolId, withCityName: true } }).then(
					(response) => {
						$scope.searchCtx.schools.items = response.data;
					});
			}

			$http.get(`/webapi/portfolios/refs/userTypes`).then((response) => {
				$scope.filter.items.userTypes = response.data;
			});

			$http.get(`/webapi/portfolios/refs/accessTypes`).then((response) => {
				$scope.data.accessTypes = response.data;
				$scope.data.accessTypes.push({id: -1, key: null, name: "Не выбрано", order: 3});
			});

			$http.get(`/webapi/portfolios/${$scope.data.portfolioId}/groups`)
				.then((response) => {
					const equalizer = new TreeEqualizer(response.data, (g) => g.order);
					$scope.filter.items.groups = equalizer.execute();
					$scope.filter.items.groups.unshift({id: -1, treeItemName: "Все разделы"});
					$scope.state.ready = true;
				});

			$scope.setAccessType = (user, accessType) => {
				user.accessType = accessType;
				const member = _.findWhere($scope.data.members, { userId: user.id });
				if (member) {
					member.accessType = accessType;
				} else {
					$scope.data.members.push({ userId: user.id, accessType: accessType });
				}
				$scope.state.dataChanged = true;
			}

			$scope.load = () => {
				const params = {
					schoolId: $scope.filter.selected.schoolId,
					page: $scope.paging.page,
					pageSize: $scope.paging.pageSize,
					userType: $scope.filter.selected.userType
				};

				const loadRights = $http.get(`/webapi/portfolios/${$scope.data.portfolioId}/members`, { params: {schoolId: $scope.filter.selected.schoolId, groupId: $scope.filter.selected.groupId} })
					.then((response) => {
						$scope.data.members = response.data;
					});

				const loadMembers = $http.get(`/webapi/portfolios/members`, { params })
					.then((response) => {
						$scope.data.users = response.data;
						$scope.paging.totalcount = parseInt(response.headers("count"));
						$scope.paging.show = $scope.paging.totalcount > $scope.paging.pageSize;
					});

				$q.all([loadRights, loadMembers]).then(() => {
					$scope.data.users = _.map($scope.data.users, (user) => {
						const member = _.findWhere($scope.data.members, { userId: user.id });
						if (member) {
							user.accessType = member.accessType;
						}
						else {
							user.accessType = null;
						}
						return user;
					});
					$scope.state.dataLoaded = true;

				});
			}

			$scope.save = () => {
				const setMembers = _.filter($scope.data.members, (member) => member.accessType !== null);
				let params = {};
				if ($scope.data.inheritance) {
					params.inheritance = true;
				}
				if ($scope.filter.selected.groupId > 0) {
					params.groupId = $scope.filter.selected.groupId;
				}
				if ($scope.filter.selected.schoolId > 0) {
					params.schoolId = $scope.filter.selected.schoolId;
				}
				$http.put(`/webapi/portfolios/${$scope.data.portfolioId}/members`, setMembers, { params })
					.then(() => {
						$scope.state.dataChanged = false;
						$alerts.success("Участники успешно сохранены");
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			}
		});


