"use strict";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("ViewPersonalPortfoliosCtrl", ($scope, $http, $route, $routeParams, $alerts, $location, $appLoader, downloadService) => {
		$.extend($scope, {
			language: language,
			editurl: "",
			data: {
				portfolio: null
			},
			state: {
				emptyData: false,
				readonly: $route.current.$$route.see
			},
			viewMode: $route.current.$$route.see,
			showViewLink: false
		});

		if ($scope.viewMode) {
			$scope.$parent.page = {
				title: 'Просмотр',
				back: { history: true },
				parent: {
					title: "Личный портфолио",
					href: `personal`
				}
			}
		} else {
			$scope.$parent.page = {
				title: "Личный портфолио"
			}
		}

		const defaultCatcher = (response) => $alerts.error(response.data.message, response.data.details);

		if (!$scope.viewMode) {
			$http.get("/webapi/portfolios/personal/see/accessGranted")
				.then((response) => $scope.showViewLink = response.data, defaultCatcher);
		}

		$scope.openDoc = (url, fileName) => {
			downloadService.downloadFile(url, fileName);
		}

		$scope.create = () => {
			$http.post(`/webapi/portfolios/personal/`)
				.then((response) => {
					$scope.data.portfolio = response.data;
					$scope.state.emptyData = false;
					$scope.editurl = `personal/${$scope.data.portfolio.id}/edit`;

					$location.path($scope.editurl);
				}, defaultCatcher);
		}

		const getPortfolio = () => {
			const handler = (response) => {
				$scope.data.portfolio = response.data;
				if ($scope.data.portfolio == null) {
					$scope.state.emptyData = true;
				} else {
					$scope.editurl = `personal/${$scope.data.portfolio.id}/edit`;
				}
				$appLoader.hide();
			}

			const userId = $scope.portfolio
				? $scope.portfolio.id
				: appContext.userId;
			$http.get(`/webapi/portfolios/personal/?userId=${userId}`)
				.then(handler, defaultCatcher);
		}

		if (!$scope.viewMode) {
			getPortfolio();
		} else {
			$scope.$watch("portfolio", getPortfolio);

			$http.get(`/webapi/portfolios/personal/see`)
				.then((response) => {
					if (!response.data) {
						$scope.state.emptyData = true;
						return;
					}
					$scope.portfolios = response.data;
					$scope.portfolio = $scope.portfolios[0];
				}, defaultCatcher);
		}
		
	});



