"use strict";

import SearchSource from "approot/global/searchSource.js";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("EditPersonalPortfolioRightsCtrl",
		($scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams) => {

			$scope.$parent.page = {
				parent: {
					title: "Личный портфолио",
					href: `personal`
				},
				back: { history: true },
				title: "Права доступа к портфолио"
			}

			angular.extend($scope,
			{
				language: language,
				filter: {
					items: {
						userTypes: []
					},
					selected: {
						schoolId: parseInt($routeParams.schoolId) || null,
						userType: parseInt($routeParams.userType) || -1
					},
					ready: () => { return $scope.filter.selected.schoolId > 0; }
				},
				data: {
					portfolioId: $routeParams.portfolioId,
					users: [],
					selected: [],
					inheritance: false
				},
				paging: {
					page: 1,
					pageSize: 20,
					totalcount: 0
				},
				state: {
					ready: false,
					dataLoaded: false,
					dataChanged: false
				}
			});

			$appLoader.hide();

			$scope.searchCtx = new SearchSource({
				schools: {
					url: "/webapi/schools/search",
					searchParam: "name",
					params: { take: 20 }
				}
			}, $http);

			if ($scope.filter.selected.schoolId > 0) {
				$http.get(`/webapi/schools/short`, { params: { id: $scope.filter.selected.schoolId, withCityName: true } }).then(
					(response) => {
						$scope.searchCtx.schools.items = response.data;
					});
			}

			$http.get(`/webapi/portfolios/refs/userTypes`).then((response) => {
				$scope.filter.items.userTypes = response.data;
			});

			$http.get(`/webapi/portfolios/personal/${$scope.data.portfolioId}/rights`)
				.then((response) => {
					$scope.data.selected = _.map(response.data, right => {
						return _.extend(right, { fromDb: true });
					});
					$scope.state.ready = true;
				});

			$scope.disabled = (user) => {
				return user.id == appContext.userId;
			}

			$scope.selected = (user) => {
				let selected = _.findWhere($scope.data.selected, { userId: user.id });
				return (selected != null && selected.accessType != 'None')
					|| $scope.disabled(user);
			}

			let toggle = (data, right) => {
				if (right) {
					right.accessType = 'Read';
					return;
				}
				
				let rightNew = {
					userId: data.id,
					accessType: 'Read'
				}
				$scope.data.selected.push(rightNew);
			}

			let untoggle = (data) => {
				if (data.fromDb) {
					data.accessType = 'None';
					return;
				}
				$scope.data.selected = _.without($scope.data.selected, data);
			}

			$scope.toggle = (user) => {
				if ($scope.disabled(user)) return;

				const searchResult = _.findWhere($scope.data.selected, { userId: user.id });
				if (searchResult && searchResult.accessType != 'None') {
					untoggle(searchResult);
				} else {
					toggle(user, searchResult);
				}

				$scope.state.dataChanged = true;
			}

			$scope.load = () => {
				const params = {
					schoolId: $scope.filter.selected.schoolId,
					page: $scope.paging.page,
					pageSize: $scope.paging.pageSize,
					userType: $scope.filter.selected.userType
				};

				$http.get(`/webapi/portfolios/users`, { params })
					.then((response) => {
						$scope.state.dataLoaded = true;
						$scope.data.users = response.data;
						$scope.paging.totalcount = parseInt(response.headers("count"));
						$scope.paging.show = $scope.paging.totalcount > $scope.paging.pageSize;
					});
			}

			$scope.save = () => {
				const additionalRights = $scope.data.selected //_.map($scope.data.selected, o => {return {userId: o.id, accessType: 'Read'}});
				$http.put(`/webapi/portfolios/personal/${$scope.data.portfolioId}/rights`, additionalRights, { })
					.then(() => {
						$scope.state.dataChanged = false;
						$alerts.success("Права успешно сохранены");
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			}
		});


