"use strict";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("PortfolioLeadersCtrl",
		($scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams, $location, $httpParamSerializer ) => {

			$scope.$parent.page = {
				parent: {
					title: language.Generic.SetupSchoolPortfolio.kTitleProjectPortfolios,
					href: `projects`
				},
				back: { history: true },
				title: language.Generic.SetupSchoolPortfolio.kPortfolioLeaders
			}

			angular.extend($scope, {
				language: language,
				filter: {
					items: {
						schools: [],
						userTypes: []
					},
					selected: {
						schoolId: -1,
						userType: 1
					},
					ready: () => { return true; }
				},
				data: {
					portfolioId: $routeParams.portfolioId,
					leaders: [],
					selected: []
				},
				state: {
					ready: false
				}
			});

			$scope.selected = (leader) => {
				return _.findWhere($scope.data.selected, { userId: leader.userId }) != null;
			}

			$scope.toggle = (leader) => {
				if (_.findWhere($scope.data.selected, { userId: leader.userId })) {
					$scope.data.selected = _.without($scope.data.selected, leader);
				} else {
					$scope.data.selected.push(leader);
				}
			}

			$http.get(`/webapi/portfolios/refs/userTypes`, {params: {onlyStuff: true}}).then((response) => {
				$scope.filter.items.userTypes = response.data;
			});

			$scope.filterViewLeaders = () => {
				let userTypeKey;
				if ($scope.filter.selected.userType > 1) {
					userTypeKey = _.findWhere($scope.filter.items.userTypes, { id: $scope.filter.selected.userType }).key;
					//userTypeKey = userTypeKey.charAt(0).toLowerCase() + userTypeKey.slice(1);
				}
				$scope.data.viewLeaders = _.filter($scope.data.leaders, (leader) => {
					if ($scope.filter.selected.schoolId > 0 && leader.schoolId !== $scope.filter.selected.schoolId) {
						return false;
					}
					if (userTypeKey && leader.userType !== userTypeKey) {
						return false;
					}
					return true;
				});
			}

			//загрузить участников
			$scope.load = () => {
				$scope.state.ready = false;
				const params = {};
				if ($scope.filter.selected.userType) {
					params.userType = $scope.filter.selected.userType;
				}
				return $http.get(`/webapi/portfolios/${$scope.data.portfolioId}/leaders`, {params})
					.then((response) => {
						$scope.data.leaders = response.data;
					})
					.then(() => {
						return $http.get(`/webapi/schools/short`, { params: { id: _.pluck($scope.data.leaders, "schoolId"), withCityName: true } });
					})
					.then((response) => {
						$scope.filter.items.schools = response.data;
						$scope.filter.items.schools.unshift({ id: -1, name: "Все" });

						const schoolIdx = _.indexBy($scope.filter.items.schools, "id");
						//добавление в dto информации по названиям орагнизаций и уровне доступа
						$scope.data.leaders = _.map($scope.data.leaders,
							(leader) => {
								//leader.accessType = _.findWhere($scope.data.accessTypes, { key: leader.accessType });
								leader.orgname = schoolIdx[leader.schoolId || -1].name;
								return leader;
							});

						//применение клиентских фильтров
						$scope.filterViewLeaders();
						$scope.state.ready = true;
					});
				
			}

			//первоначальная загрузка участников
			$scope.load().then(() => $appLoader.hide());

			//переход в редакитрование
			$scope.edit = () => {
				const params = {};
				if ($scope.filter.selected.groupId > 0) {
					params.groupId = $scope.filter.selected.groupId;
				}
				if ($scope.filter.selected.userType > 0) {
					params.userType = $scope.filter.selected.userType;
				}
				if ($scope.filter.selected.schoolId > 0) {
					params.schoolId = $scope.filter.selected.schoolId;
				}
				$location.path(`/${$scope.data.portfolioId}/leaders/edit`).search(params);
			}

			//удалить
			$scope.delete = () => {
				const params = {
					userId: _.pluck($scope.data.selected, "userId")
				};
				if ($scope.filter.selected.groupId > 0) {
					params.groupId = $scope.filter.selected.groupId;
				}

				const url = `/webapi/portfolios/${$scope.data.portfolioId}/leaders`;
				$dialogs.confirm("Вы действительно желаете удалить участников?")
					.then(() => $http.delete(url, { params }))
					.then(() => {
						$alerts.success("Участники успешно удалены");
						$scope.data.selected = [];
						$scope.load();
					}).catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			}
		});


