"use strict";

//import 'components/angular-file-upload/dist/angular-file-upload.js'

angular
	.module("irtech.netcity.school.portfolio")
	.controller("EditProjectPortfolioCtrl",
		($scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams, $controller, $location) => {

			$scope.$parent.page = {
				parent: {
					title: language.Generic.SetupSchoolPortfolio.kTitleProjectPortfolios,
					href: `projects`
				},
				back: { history: true },
				title: "Редактирование"
			}

			$scope.project = true;

			$scope.state = {
				fullAccess: false,
				groupDataReadonly: true
			};

			//наследование от базового контроллера
			$controller("EditPortfolioCtrl", { $scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams, $controller });


			const checkPortfolioAccess = (portfolio) => {
				const userId = parseInt(appContext.userId);
				const isLeader = _.some(portfolio.leaders, (leader) => { return leader.userId === userId });

				$scope.state.fullAccess = isLeader;

				if (isLeader) {
					//$scope.writeAccess.full = true;
					return;
				}

				$http.get(`/webapi/portfolios/${$scope.data.portfolioId}/access`).then((response) => {
					$scope.data.rights = response.data;
					initGroupRights();
				});
			};

			$scope.$watch("data.portfolio", (portfolio) => {
				if (portfolio) {
					checkPortfolioAccess(portfolio);
				}
			});

			const initGroupRights = (group) => {
				group = group || $scope.data.group;

				if ($scope.state.fullAccess) {
					$scope.state.groupDataReadonly = false;
				} else {
					$scope.state.groupDataReadonly = !_.some($scope.data.rights, (accessInfo) => accessInfo.groupId === group.id && accessInfo.accessType === "Write");
				}
			}

			$scope.$watch("data.group", (group) => {
				if (group) {
					initGroupRights(group);
				}
			});

			//редактирование участников портфолио-проекта
			$scope.members = () => {
				$location.path(`/${$scope.data.portfolioId}/members/`);
			}

			//редактирование руководителей портфолио-проекта
			$scope.leaders = () => {
				$location.path(`/${$scope.data.portfolioId}/leaders/`);
			}

			//переименование портфолио проекта
			$scope.rename = () => {
				const modalInstance = $uibModal.open({
					templateUrl: "/static/dist/app/school/portfolio/projects/edit/renamePortfolioTemplate.html",
					controller: "RenamePortfolioCtrl",
					size: "md",
					resolve: {
						portfolio: () => {
							return{
								id: $scope.data.portfolio.id,
								name: $scope.data.portfolio.name
							};
						}
					}
				});

				modalInstance.result
					.then((editedPortfolio) => {
						$scope.data.portfolio = angular.extend($scope.data.portfolio, editedPortfolio);
					})
					.catch((res) => {
						if (res !== 'cancel') {
							throw res;
						}
					});
			}
		})
	.controller("RenamePortfolioCtrl",
		($scope, $http, $alerts, $uibModalInstance, portfolio) => {
			$scope.header = "Редактирование имени портфолио";

			$.extend($scope,
			{
				language: language,
				data: {
					portfolio: portfolio
				}
			});

			$scope.save = () => {
				if (!$scope.portfolioForm.$valid) {
					$scope.portfolioForm.$displayErrors = true;
					return;
				}

				$http.put(`/webapi/portfolios/projects/`, $scope.data.portfolio)
					.then(() => {
						$uibModalInstance.close($scope.data.portfolio);
						$alerts.success("Имя успешно изменено");
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});

			};

			$scope.cancel = () => {
				$uibModalInstance.dismiss("cancel");
			}
		});



