class TreeEqualizer {
	constructor(tree, sorter) {
		this.tree = tree;
		this.sorter = sorter;
	}

	execute(excludeGroup) {

		const groupReducer = (memo, group) => {
			group.treeItemName = "";
			for (let i = 1; i < memo.level; i++) {
				group.treeItemName += "\u00A0\u00A0\u00A0\u00A0";
			}
			group.treeItemName += group.name;
			group.treeLevel = memo.level;

			if (group === excludeGroup) {
				return {
					groups: memo.groups,
					level: memo.level
				};
			}

			memo.groups = memo.groups.concat([group]);
			const sortedGroups = _.sortBy(group.groups, this.sorter);

			const reduceRes = _.reduce(sortedGroups, groupReducer, { groups: [], level: memo.level + 1 });

			return {
				groups: memo.groups.concat(reduceRes.groups),
				level: memo.level
			};
		};

		const sortedGroups = _.sortBy(this.tree, this.sorter);

		const res = _.reduce(sortedGroups, groupReducer, { groups: [], level: 1 });

		return res.groups;
	}
}

module.exports = TreeEqualizer


