"use strict";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("ViewProjectPortfoliosCtrl", ($scope, $http, $routeParams, $location, $dialogs, $appLoader, $alerts, downloadService) => {
		const portfolioId = $routeParams.portfolioId;

		$scope.$parent.page = {
			parent: {
				title: language.Generic.SetupSchoolPortfolio.kTitleProjectPortfolios,
				href: "projects"
			},
			title: ""
		}

		$.extend($scope, {
			language: language,
			editurl: `${portfolioId}/edit`,
			data: {
				portfolio: null
			},
			state: {
				readonly: true
			},
			ready: false
		});

		$scope.$watch("data.portfolio", (portfolio) => {
			if (portfolio) {
				$scope.$parent.page.title = portfolio.name;
				$appLoader.hide();
			}
		});

		const checkPortfolioAccess = (portfolio) => {
			const userId = parseInt(appContext.userId);
			const isLeader = _.some(portfolio.leaders, (leader) => { return leader.userId === userId });
			if (isLeader) {
				$scope.state.readonly = false;
				return;
			}

			$http.get(`/webapi/portfolios/${portfolioId}/access`).then((response) => {
				$scope.state.readonly = !(response.data != null && response.data.length > 0);
			});
		};

		$scope.openDoc = (url, fileName) => {
			downloadService.downloadFile(url, fileName);
		}

		$http.get(`/webapi/portfolios/${portfolioId}`)
			.then((response) => {
				$scope.data.portfolio = response.data;
				$scope.ready = true;
				checkPortfolioAccess($scope.data.portfolio);
			});
	
		$scope.delete = () => {
			$dialogs.confirm("Вы действительно желаете удалить портфолио?")
				.then(() => $http.delete(`/webapi/portfolios/projects/${portfolioId}`))
				.then(() => {
					$alerts.success("Портфолио успешно удалено");
					$location.path($scope.$parent.page.parent.href);
					setTimeout(function () {
						$scope.$apply();
					}, 0);
				}).catch((response) => {
					$alerts.error(response.data.message, response.data.details);
				});
		}
	});



