"use strict";

import TreeEqualizer from "../../common/treeEqualizer.js";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("PortfolioMembersCtrl",
		($scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams, $location, $httpParamSerializer ) => {

			$scope.$parent.page = {
				parent: {
					title: language.Generic.SetupSchoolPortfolio.kTitleProjectPortfolios,
					href: `projects`
				},
				back: { history: true },
				title: language.Generic.SetupSchoolPortfolio.kPortfolioMembers
			}

			angular.extend($scope, {
				language: language,
				filter: {
					items: {
						schools: [],
						groups: [],
						userTypes: []
					},
					selected: {
						schoolId: -1,
						groupId: parseInt($routeParams.groupId) || -1,
						userType: -1
					},
					ready: () => { return true; }
				},
				data: {
					portfolioId: $routeParams.portfolioId,
					members: [],
					selected: []
				},
				state: {
					ready: false
				}
			});

			
			$scope.isInherited = (member) => {
				return $scope.filter.selected.groupId > 0 && member.groupId != $scope.filter.selected.groupId;
			}

			$scope.selected = (member) => {
				return _.findWhere($scope.data.selected, { userId: member.userId }) != null;
			}

			$scope.toggle = (member) => {
				if (_.findWhere($scope.data.selected, { userId: member.userId })) {
					$scope.data.selected = _.without($scope.data.selected, member);
				} else {
					$scope.data.selected.push(member);
				}
			}

			$http.get(`/webapi/portfolios/refs/userTypes`).then((response) => {
				$scope.filter.items.userTypes = response.data;
			});

			$http.get(`/webapi/portfolios/refs/accessTypes`).then((response) => {
				$scope.data.accessTypes = response.data;
			});

			$http.get(`/webapi/portfolios/${$scope.data.portfolioId}/groups`)
				.then((response) => {
					//разложение дерева разделов в плоский список с отступами
					const equalizer = new TreeEqualizer(response.data, (g) => g.order);
					$scope.filter.items.groups = equalizer.execute();
					$scope.filter.items.groups.unshift({id: -1, treeItemName: "Все разделы"});
				});

			$scope.filterViewMembers = () => {
				let userTypeKey;
				if ($scope.filter.selected.userType > 0) {
					userTypeKey = _.findWhere($scope.filter.items.userTypes, { id: $scope.filter.selected.userType }).key;
					userTypeKey = userTypeKey.charAt(0).toLowerCase() + userTypeKey.slice(1);
				}
				$scope.data.viewMembers = _.filter($scope.data.members, (member) => {
					if ($scope.filter.selected.schoolId > 0 && member.schoolId !== $scope.filter.selected.schoolId) {
						return false;
					}
					if (userTypeKey && !member.userTypes[userTypeKey]) {
						return false;
					}
					return true;
				});
			}

			//загрузить участников
			$scope.load = () => {
				$scope.state.ready = false;
				const params = {};
				if ($scope.filter.selected.groupId > 0) {
					params.groupId = $scope.filter.selected.groupId;
				}
				//if ($scope.filter.selected.userType > 0) {
				//	params.userType = $scope.filter.selected.userType;
				//}
				return $http.get(`/webapi/portfolios/${$scope.data.portfolioId}/members`, {params})
					.then((response) => {$scope.data.members = response.data;})
					.then(() => { return $http.get(`/webapi/schools/short`, { params: { id: _.pluck($scope.data.members, "schoolId"), withCityName: true } }) })
					.then((response) => {
						const schoolIdx = _.indexBy(response.data, "id");
						$scope.filter.items.schools = response.data;
						$scope.filter.items.schools.unshift({ id: -1, name: "Все" });

						//добавление в dto информации по названиям орагнизаций и уровне доступа
						$scope.data.members = _.map($scope.data.members,
							(member) => {
								member.accessType = _.findWhere($scope.data.accessTypes, { key: member.accessType });
								if (member.schoolId > 0) {
									member.orgname = schoolIdx[member.schoolId].name;
								}
								return member;
							});

						//применение клиентских фильтров
						$scope.filterViewMembers();
						$scope.state.ready = true;
					});
			}

			//первоначальная загрузка участников
			$scope.load().then(() => $appLoader.hide());

			//переход в редакитрование
			$scope.edit = () => {
				const params = {};
				if ($scope.filter.selected.groupId > 0) {
					params.groupId = $scope.filter.selected.groupId;
				}
				if ($scope.filter.selected.userType > 0) {
					params.userType = $scope.filter.selected.userType;
				}
				if ($scope.filter.selected.schoolId > 0) {
					params.schoolId = $scope.filter.selected.schoolId;
				}
				$location.path(`/${$scope.data.portfolioId}/members/edit`).search(params);
			}

			//удалить
			$scope.delete = () => {
				const params = {
					userId: _.pluck($scope.data.selected, "userId")
				};
				if ($scope.filter.selected.groupId > 0) {
					params.groupId = $scope.filter.selected.groupId;
				}

				const url = `/webapi/portfolios/${$scope.data.portfolioId}/members`;
				$dialogs.confirm("Вы действительно желаете удалить участников?")
					.then(() => $http.delete(url, { params }))
					.then(() => {
						$alerts.success("Участники успешно удалены");
						$scope.data.selected = [];
						$scope.load();
					}).catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			}
		});


