"use strict";

import * as Roles from "approot/global/references/roles.js";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("ListProjectPortfoliosCtrl", ($scope, $http, $q, $alerts, $dialogs, $appLoader, $uibModal) => {

		

		$scope.$parent.page = {
			title: language.Generic.SetupSchoolPortfolio.kTitleProjectPortfolios
		}

		$.extend($scope, {
			language: language,
			data: {
				self: {
					portfolios: []
				},
				others: {
					portfolios: []
				}
			},
			state: {
				dataReady: false
			}
		});

		const queries = [
			$http.get("/webapi/portfolios/projects").then((response) => {
				$scope.data.self.portfolios = response.data;
			})
		];

		if (_.contains(context.roles, Roles.admin)) {
			queries.push(
				$http.get("/webapi/portfolios/projects?others=true").then((response) => {
					$scope.data.others.portfolios = response.data;
				})
			);
		}

		$q.all(queries).then(() => {
			$appLoader.hide();
			$scope.state.dataReady = true;
		});

		$scope.create = () => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/portfolio/projects/list/createProjectPortfolio.html",
				controller: "CreateProjectPortfolioCtrl",
				size: "md"
			});

			modalInstance.result.then((createdPortfolio) => {
				$scope.data.self.portfolios.push(createdPortfolio);
			});
		}

		$scope.delete = (portfolio) => {
			$dialogs.confirm("Вы действительно желаете удалить портфолио?")
				.then(() => $http.delete(`/webapi/portfolios/projects/${portfolio.id}`))
				.then(() => {
					$scope.data.self.portfolios = _.without($scope.data.self.portfolios, portfolio);
					$alerts.success("Портфолио успешно удалено");
				}).catch((response) => {
					$alerts.error(response.data.message, response.data.details);
				});
		}
	})
	.controller("CreateProjectPortfolioCtrl", ($scope, $http, $alerts, $uibModalInstance) => {
		$scope.header = "Создание портфолио";

		$.extend($scope, {
			language: language,
			data: {
				portfolio: {
				}
			}
		});

		$scope.save = () => {
			if (!$scope.portfolioForm.$valid) {
				$scope.portfolioForm.$displayErrors = true;
				return;
			}

			$http.post(`/webapi/portfolios/projects/`, $scope.data.portfolio)
				.then((response) => {
					$uibModalInstance.close(response.data);
					$alerts.success("Портфолио успешно создано");
				})
				.catch((response) => {
					$alerts.error(response.data.message, response.data.details);
				});

		};

		$scope.cancel = () => {
			$uibModalInstance.dismiss("cancel");
		}
	})

;



