const module = angular
	.module("irtech.netcity.school.portfolio",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"ngFileUpload", "ui.tree", "irtech.netcity.common", "irtech.netcity.ui-components",
		"irtech.netcity.school.portfolio.common"
	]);

require("./common/view/portfolioDir.js");
require("./common/edit/editPortfolioCtrls.js");
require("./personal/view/viewPersonalPortfolioCtrl.js");
require("./personal/edit/editPersonalPortfolioCtrl.js");
require("./personal/edit/rights/editRights.js");
require("./projects/list/listProjectPortfoliosCtrl.js");
require("./projects/view/viewProjectPortfoliosCtrl.js");
require("./projects/edit/editProjectPortfolio.js");
require("./projects/members/portfolioMembers.js");
require("./projects/members/edit/editPortfolioMembers.js");
require("./projects/leaders/portfolioLeaders.js");
require("./projects/leaders/edit/editPortfolioLeaders.js");

	module.filter("extension", () => {
		return (input) => {
			return input ? input.split(".").pop() : "";
		}
	})
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/personal/", {
				templateUrl: "/static/dist/app/school/portfolio/personal/view/template.html",
				controller: "ViewPersonalPortfoliosCtrl"
			})
			.when("/personal/see", {
				templateUrl: "/static/dist/app/school/portfolio/personal/view/template.html",
				controller: "ViewPersonalPortfoliosCtrl",
				see: true
			})
			.when("/personal/:portfolioId/rights/", {
				templateUrl: "/static/dist/app/school/portfolio/common/edit/editUserRights.html",
				controller: "EditPersonalPortfolioRightsCtrl"
			})
			.when("/personal/:portfolioId/edit", {
				templateUrl: "/static/dist/app/school/portfolio/common/edit/template.html",
				controller: "EditPersonalPortfolioCtrl"
			})
			.when("/projects/", {
				templateUrl: "/static/dist/app/school/portfolio/projects/list/template.html",
				controller: "ListProjectPortfoliosCtrl"
			})
			.when("/projects/:portfolioId", {
				templateUrl: "/static/dist/app/school/portfolio/projects/view/template.html",
				controller: "ViewProjectPortfoliosCtrl"
			})
			.when("/:portfolioId/edit", {
				templateUrl: "/static/dist/app/school/portfolio/common/edit/template.html",
				controller: "EditProjectPortfolioCtrl"
			})
			.when("/:portfolioId/members", {
				templateUrl: "/static/dist/app/school/portfolio/projects/members/template.html",
				controller: "PortfolioMembersCtrl"
			})
			.when("/:portfolioId/members/edit", {
				templateUrl: "/static/dist/app/school/portfolio/projects/members/edit/template.html",
				controller: "EditPortfolioMembersCtrl"
			})
			.when("/:portfolioId/leaders/", {
				templateUrl: "/static/dist/app/school/portfolio/projects/leaders/template.html",
				controller: "PortfolioLeadersCtrl"
			})
			.when("/:portfolioId/leaders/edit", {
				templateUrl: "/static/dist/app/school/portfolio/common/edit/editUserRights.html",
				controller: "EditPortfolioLeadersCtrl"
			})
			.otherwise({
				templateUrl: "/static/dist/app/school/portfolio/projects/list/template.html",
				controller: "ListProjectPortfoliosCtrl"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



