"use strict";

angular
	.module("irtech.netcity.school.portfolio")
	.controller("EditPersonalPortfolioCtrl",
		($scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams, $controller, $location) => {

			$scope.$parent.page = {
				parent: {
					title: "Личный портфолио",
					href: `personal`
				},
				back: { history: true },
				title: "Редактирование"
			}

			$scope.project = false;
			$scope.personal = true;

			$scope.state = {
				fullAccess: true,
				groupDataReadonly: false
			};
			
			//наследование от базового контроллера
			$controller("EditPortfolioCtrl", { $scope, $http, $q, $uibModal, $appLoader, $alerts, $dialogs, $routeParams, $controller});

			$scope.editRights = () => $location.path(`/personal/${$scope.data.portfolioId}/rights/`);
		});



